ee:message.ee:set-payload:
%dw 2.0
output application/xml

ns ns0 http://legacy.acme.com/ordermanagement/

---
ns0#UpdateOrderRequest: {
    ns0#orderId: attributes.uriParams.orderId,
    ns0#customerId: payload.customerId,

    ns0#items: {
        (payload.items map (item) -> {
            ns0#item: {
                ns0#productId: item.productId,
                ns0#productName: item.productName,
                ns0#quantity: item.quantity,
                ns0#unitPrice: item.unitPrice
            }
        })
    },

    ns0#shippingAddress: {
        ns0#line1: payload.shippingAddress.line1,
        ns0#city: payload.shippingAddress.city,
        ns0#state: payload.shippingAddress.state,
        ns0#postalCode: payload.shippingAddress.postalCode,
        ns0#country: payload.shippingAddress.country
    }
}

%dw 2.0
output application/json
---
{
  status: "UP"
} as Object {encoding: "UTF-8", mediaType: "application/json"}

%dw 2.0
output application/xml writeDeclaration=true, encoding="UTF-8"

ns legacy http://legacy.acme.com/ordermanagement/

---
{
    legacy#GetOrderStatusRequest: {
        orderId: attributes.uriParams.orderId
    }
}

%dw 2.0 output application/json
ns soap http://schemas.xmlsoap.org/soap/envelope/ ns ns0 http://legacy.acme.com/ordermanagement/ ---
{ orderId: payload.soap#Body.ns0#GetOrderStatusResponse.orderId, status: payload.soap#Body.ns0#GetOrderStatusResponse.status }

%dw 2.0
output application/xml writeDeclaration=true, encoding="UTF-8"

ns legacy http://legacy.acme.com/ordermanagement/

---
{
    legacy#GetOrderDetailsRequest: {
        orderId: attributes.uriParams.orderId
    }
}

%dw 2.0
output application/xml writeDeclaration=true, encoding="UTF-8"

ns legacy http://legacy.acme.com/ordermanagement/

---
{
    legacy#ListOrdersByCustomerRequest: {
        customerId: attributes.queryParams.customerId
    }
}

%dw 2.0
output application/json

ns soap http://schemas.xmlsoap.org/soap/envelope/
ns ord http://legacy.acme.com/ordermanagement/

fun toOrder(order) = {
    orderId: order.orderId as String,
    customerId: order.customerId as String,
    orderDate: ((order.orderDate as LocalDateTime) as String {
        format: "yyyy-MM-dd'T'HH:mm:ss"
    }) ++ "Z",
    status: order.status as String,
    totalAmount: order.totalAmount as Number,
    currency: order.currency as String,

    shippingAddress: {
        line1: order.shippingAddress.line1 as String,
        city: order.shippingAddress.city as String,
        state: order.shippingAddress.state as String,
        postalCode: order.shippingAddress.postalCode as String,
        country: order.shippingAddress.country as String
    },

    items: (order.*items.item default []) map (item) -> {
        productId: item.productId as String,
        productName: item.productName as String,
        quantity: item.quantity as Number,
        unitPrice: item.unitPrice as Number
    }
}

var response =
    payload.soap#Body.ord#ListOrdersByCustomerResponse

---
{
    orders: response.orders.*order map toOrder($)
}

%dw 2.0
output application/xml writeDeclaration=true, encoding="UTF-8"

ns legacy http://legacy.acme.com/ordermanagement/

---
{
    legacy#CancelOrderRequest: {
        orderId: attributes.uriParams.orderId,
        cancellationReason: payload.cancellationReason
    }
}

%dw 2.0
output application/xml writeDeclaration = true, encoding = "UTF-8"
ns ord http://legacy.acme.com/ordermanagement/
---
ord#CreateOrderRequest: {
	ord#customerId: payload.customerId,
	ord#items: {
		(payload.items map (item) -> {
			ord#item: {
				ord#productId: item.productId,
				ord#productName: item.productName,
				ord#quantity: item.quantity,
				ord#unitPrice: item.unitPrice
			}
		})
	},
	ord#shippingAddress: {
		ord#line1: payload.shippingAddress.line1,
		ord#city: payload.shippingAddress.city,
		ord#state: payload.shippingAddress.state,
		ord#postalCode: payload.shippingAddress.postalCode,
		ord#country: payload.shippingAddress.country
	},
	ord#currency: payload.currency
}
